<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Quote Generator Online','description'=>'Generate an inspiring random quote and copy it instantly.','url'=>'https://smarttoolz.in/tools/quote-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">QUOTE GENERATOR</span><h1>Random Quote Generator</h1><p>Get a fresh motivational quote whenever you need one.</p></section><section class="tool-workspace"><div class="tool-panel" style="text-align:center"><blockquote id="q" style="font-size:24px;line-height:1.6;font-weight:800">Click generate for a quote.</blockquote><button id="go" class="tool-btn">New Quote</button><button id="copy" class="tool-btn" style="margin-top:10px">Copy Quote</button></div></section></main><script>(()=>{const a=['Small steps create big change.','Make today useful.','Consistency turns effort into progress.','Start simple, then improve.','Good work compounds over time.','Build something people can use.','Focus on progress, not perfection.','Clarity makes action easier.'];const q=document.getElementById('q');document.getElementById('go').onclick=()=>q.textContent=a[Math.random()*a.length|0];document.getElementById('copy').onclick=()=>navigator.clipboard.writeText(q.textContent);document.getElementById('go').click()})();</script><?php smarttoolz_tool_page_end(); ?>